"""`.KK`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.KK'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Shader', 'NodeSocketShader')
    t.socket('INPUT', 'Force visibility', 'NodeSocketInt', subtype='FACTOR', min_value=0, max_value=2)
    t.socket('INPUT', 'Dark', 'NodeSocketColor', default_value=(0.5, 0.5, 0.5, 1.0))
    t.socket('INPUT', 'Light', 'NodeSocketColor', default_value=(0.5, 0.5, 0.5, 1.0))
    t.socket('INPUT', 'Normal', 'NodeSocketColor', default_value=(0.5, 0.5, 1.0, 1.0))
    t.socket('INPUT', 'Normal alpha', 'NodeSocketFloat', min_value=0.0, max_value=1.0)
    t.socket('INPUT', 'Normal detail', 'NodeSocketColor')
    t.socket('INPUT', 'Normal detail alpha', 'NodeSocketFloat', min_value=0.0, max_value=1.0)
    t.socket('INPUT', 'Permalight mask', 'NodeSocketColor')
    t.socket('INPUT', 'Alpha mask', 'NodeSocketColor', default_value=(0.8, 0.8, 0.8, 1.0))
    t.socket('INPUT', 'Alpha mask alpha', 'NodeSocketFloat', default_value=0.5, min_value=-10000.0, max_value=10000.0)
    t.socket('INPUT', 'Light alpha', 'NodeSocketFloat')
    t.socket('INPUT', 'Disable permalight mask', 'NodeSocketBool', description='Amount of influence the node exerts on the image')
    t.socket('INPUT', 'Hidden', 'NodeSocketFloat', subtype='FACTOR', min_value=0.0, max_value=1.0)

    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (651.875, 21.658833),
    })
    t.node('NodeGroupInput', 'input', props={
        'location': (-962.0644, -3.6315908),
        'width': 187.39368,
    })
    t.node('ShaderNodeMixShader', 'mix', props={
        'location': (229.85538, 33.293686),
    })
    t.node('ShaderNodeBsdfTransparent', 'Transparent BSDF', hide_inputs=('Color', 'Weight'), props={
        'location': (34.078903, -105.8488),
    })
    t.node('ShaderNodeMix', 'mixrgb', inputs={'Factor_Float': 0.5}, hide_inputs=('Factor_Vector', 'A_Float', 'B_Float', 'A_Vector', 'B_Vector'), outputs={'Result_Color': (0.0, 0.0, 0.0, 0.0)}, hide_outputs=('Result_Float', 'Result_Vector'), props={
        'location': (57.766716, 231.36678),
        'data_type': 'RGBA',
    })
    t.node('ShaderNodeGroup', 'shade', inputs={'Use Normals?': 0.0}, props={
        'node_tree': lib.group('.Toon shading'),
        'location': (-508.96613, 84.0364),
        'width': 247.78687,
    })
    t.node('ShaderNodeGroup', 'AlphaMask Stage Switch', props={
        'node_tree': lib.group('.KK alphamask parser'),
        'location': (-515.9635, -197.82063),
        'width': 251.21655,
        'label': 'AlphaMask Stage Switch',
    })
    t.node('NodeGroupInput', 'Group Input.001', hide_outputs=('Force visibility', 'Normal', 'Normal alpha', 'Normal detail', 'Normal detail alpha', 'Permalight mask', 'Alpha mask', 'Alpha mask alpha', 'Light alpha', 'Disable permalight mask', 'Hidden', 13), props={
        'location': (-131.88033, 43.99052),
        'width': 118.072266,
    })
    t.node('ShaderNodeHueSaturation', 'Hue/Saturation/Value', inputs={'Value': 0.0}, hide_inputs=('Hue', 'Saturation', 'Value'), props={
        'location': (-699.59344, -161.04459),
        'hide': True,
    })
    t.node('ShaderNodeBsdfTransparent', 'hidden.transparent', props={
        'location': (251.87497, -128.34117),
        'label': 'hidden.transparent',
    })
    t.node('ShaderNodeMixShader', 'hidden.mix', props={
        'location': (431.87497, 21.658833),
        'label': 'hidden.mix',
    })

    t.link('shade', 'Toon shading', 'mixrgb', 'Factor_Float')
    t.link('Transparent BSDF', 'BSDF', 'mix', 'Shader')
    t.link('AlphaMask Stage Switch', 'Value', 'mix', 'Fac')
    t.link('mixrgb', 'Result_Color', 'mix', 'Shader_001')
    t.link('input', 'Alpha mask alpha', 'AlphaMask Stage Switch', 'Alphamask alpha')
    t.link('input', 'Normal detail', 'shade', 'Normal detail color')
    t.link('input', 'Normal', 'shade', 'Normal color')
    t.link('input', 'Normal detail alpha', 'shade', 'Normal detail alpha')
    t.link('input', 'Normal alpha', 'shade', 'Normal alpha')
    t.link('input', 'Light alpha', 'AlphaMask Stage Switch', 'Light image alpha')
    t.link('Hue/Saturation/Value', 'Color', 'shade', 'Permalight mask')
    t.link('input', 'Force visibility', 'AlphaMask Stage Switch', 'Force visibility?')
    t.link('input', 'Alpha mask', 'AlphaMask Stage Switch', 'Alphamask color')
    t.link('Group Input.001', 'Dark', 'mixrgb', 'A_Color')
    t.link('Group Input.001', 'Light', 'mixrgb', 'B_Color')
    t.link('input', 'Permalight mask', 'Hue/Saturation/Value', 'Color')
    t.link('input', 'Disable permalight mask', 'Hue/Saturation/Value', 'Fac')
    t.link('mix', 'Shader', 'hidden.mix', 'Shader')
    t.link('hidden.transparent', 'BSDF', 'hidden.mix', 'Shader_001')
    t.link('input', 'Hidden', 'hidden.mix', 'Fac')
    t.link('hidden.mix', 'Shader', 'Group Output', 'Shader')
    return t
